$("#create_order").on('click', function (e) {



    e.preventDefault();



    create_customer_order();



});



function create_customer_order() {



    var order_for = $("input[name='order[order_for]']:checked").val();



    if ($('#select_karigar').val() == null || $('#select_karigar').val() == '') {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Select Karigar" });



    }



    else if ($('.smith_due_dt').val() == '') {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Select Due Date" });



    }



    else if ((order_for == 2 || order_for == 3) && ($('#select_order_no').val() == null || $('#select_order_no').val() == '')) {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Select Order No" });



    }



    // CPO-05: a Common PO keeps its bullion lines in #cpo_item_detail, not
    // #item_detail, so the empty-table gate has to look at whichever table is
    // actually in use. Without this a Common PO can never be saved.
    else if (($('#item_detail > tbody  > tr').length == 0) && (order_for == 1)
             && !($('#common_po').is(':checked') && $('#cpo_item_detail > tbody > tr').length > 0)) {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'No Record Found..' });



    }

    else if ($('#common_po').is(':checked') && $('#cpo_item_detail > tbody > tr').length == 0) {

        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'Add at least one bullion item' });

    }



    else if (($('#purchase_details > tbody  > tr').length == 0) && (order_for == 2)) {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'No Record Found..' });



    }



    else {



        $("div.overlay").css("display", "block");



        $('#create_stock_order').prop('disabled', true);



        var form_data = $('#order_submit').serialize();



        /* PO-EDIT-5: the amendment reuses this whole function — the same form, the
           same validation above — and only changes where it posts. A PO id in the
           hidden field means we arrived through purchase/edit/{id}. */
        var po_edit_id = $('#id_customerorder').val();

        var save_action = (po_edit_id && parseInt(po_edit_id, 10) > 0) ? "po_update" : "save";

        var url = base_url + "index.php/admin_ret_purchase/purchase/" + save_action + "?nocache=" + my_Date.getUTCSeconds();



        $.ajax({



            url: url,



            data: form_data,



            type: "POST",



            dataType: "JSON",



            success: function (data) {



                if (data.status) {



                    location.href = base_url + 'index.php/admin_ret_purchase/purchase/pur_order';



                    $.toaster({ priority: 'success', title: 'Warning!', message: '' + "</br>" + data.msg });



                    $("div.overlay").css("display", "none");



                } else {



                    $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + data.msg });



                    $("div.overlay").css("display", "none");



                }







            },



            error: function (error) {



                $("div.overlay").css("display", "none");



            }



        });



        $('#create_stock_order').prop('disabled', false);



    }



}



$('#pur_ord_search').on('click', function () {



    get_purchase_order_list();



});



function get_purchase_order_list() {



    $("div.overlay").css("display", "block");



    my_Date = new Date();



    $.ajax({



        url: base_url + "index.php/admin_ret_purchase/purchase/purchase_order?nocache=" + my_Date.getUTCSeconds(),



        dataType: "JSON",



        type: "POST",



        data: { 'from_date': $('#rpt_from_date').html(), 'to_date': $('#rpt_to_date').html(), 'order_for': $('#select_order').val() },



        success: function (data) {



            var list = data.list;



            var oTable = $('#order_list').DataTable();



            oTable.clear().draw();



            if (list != null && list.length > 0) {



                oTable = $('#order_list').dataTable({



                    "bDestroy": true,



                    "bInfo": true,



                    "bFilter": true,



                    "bSort": true,



                    "order": [[0, "desc"]],



                    "dom": 'lBfrtip',



                    "buttons": ['excel', 'print'],



                    "tableTools": { "buttons": [{ "sExtends": "xls", "oSelectorOpts": { page: 'current' } }, { "sExtends": "pdf", "oSelectorOpts": { page: 'current' } }] },



                    "aaData": list,



                    "aoColumns": [



                        {
                            "mDataProp": function (row, type, val, meta) {



                                if (row.order_status <= 3) {



                                    return '<input type="checkbox" class="id_customerorder" name="id_customerorder[]" value="' + row.id_customerorder + '"/><input type="hidden" class="cus_ord_ref" name="cus_ord_ref[]" value="' + row.cus_ord_ref + '"/>' + row.id_customerorder;



                                } else {



                                    return row.id_customerorder;



                                }



                            },



                        },



                        { "mDataProp": "pur_no" },



                        { "mDataProp": "order_date" },



                        {
                            "mDataProp": function (row, type, val, meta) {



                                return '<span class="badge bg-' + row.color + '">' + row.order_status_msg + '</span>';



                            },



                        },



                        { "mDataProp": "karigar_name" },



                        { "mDataProp": "mobile" },



                        { "mDataProp": "order_for" },

                        // CPO-06: PO Type + PO Value columns. Renderers live in
                        // ret_common_po.js so the feature stays in one file; guarded so
                        // this list still works when that file is absent (a client that
                        // has not taken the feature) rather than throwing per row.
                        {
                            "mDataProp": function (row, type, val, meta) {
                                return (window.CommonPO && window.CommonPO.renderListType)
                                    ? window.CommonPO.renderListType(row) : '-';
                            }
                        },
                        {
                            "mDataProp": function (row, type, val, meta) {
                                return (window.CommonPO && window.CommonPO.renderListValue)
                                    ? window.CommonPO.renderListValue(row) : '-';
                            }
                        },
                        {
                            "mDataProp": function (row, type, val, meta) {
                                return (window.CommonPO && window.CommonPO.renderListLedger)
                                    ? window.CommonPO.renderListLedger(row) : '-';
                            }
                        },
                        {
                            "mDataProp": function (row, type, val, meta) {
                                return (window.CommonPO && window.CommonPO.renderListTrace)
                                    ? window.CommonPO.renderListTrace(row) : '';
                            }
                        },

                        { "mDataProp": "order_pcs" },



                        {
                            "mDataProp": function (row, type, val, meta) {



                                return parseFloat(row.order_approx_wt).toFixed(3);



                            }



                        },







                        {
                            "mDataProp": function (row, type, val, meta) {



                                return parseFloat(row.delivered_qty);



                            }



                        },







                        {
                            "mDataProp": function (row, type, val, meta) {



                                return parseFloat(row.delivered_wt).toFixed(3);



                            }



                        },







                        { "mDataProp": "order_no" },


                        { "mDataProp": "cus_order_branch" },

                        {
                            "mDataProp": function (row, type, val, meta) {

                                return row.smith_due_date ? row.smith_due_date : '-';

                            }
                        },

                        {
                            "mDataProp": function (row, type, val, meta) {

                                return row.rejection_reason ? row.rejection_reason : '-';

                            }
                        },

                        {
                            "mDataProp": function (row, type, val, meta) {

                                return row.rejected_at ? row.rejected_at : '-';

                            }
                        },


                        {
                            "mDataProp": function (row, type, val, meta) {

                                id = row.id_customerorder;

                                print_url = base_url + 'index.php/admin_ret_purchase/get_karigar_acknowladgement/' + id;

                                action_content = '<a href="#" onclick="send_karigar_sms(' + id + ',' + row.mobile + ')"  class="btn btn-success" data-toggle="tooltip" title="Send WhatsApp / Email"><i class="fa fa-whatsapp" aria-hidden="true"></i></a><a href="' + print_url + '" target="_blank" class="btn btn-info btn-print" data-toggle="tooltip" title="Vendor acknowledgement "><i class="fa fa-print" ></i></a>';

                                /* PO-EDIT-5: amend an existing PO instead of cancelling and
                                   re-raising it. Offered only while the order is still an
                                   intention — 0 Ordered, 1 Process, 2 Confirm, 3 Work in
                                   Progress, 10 Waiting for Approval, 11 Approved. 4/5 mean
                                   metal is moving and 6/7/8 are terminal.

                                   This is the courtesy check only: the edit screen refuses
                                   to render and the update endpoint refuses to save if a
                                   bill, an advance or a receipt exists, none of which this
                                   row knows about. */
                                var po_editable = [0, 1, 2, 3, 10, 11];
                                if (po_editable.indexOf(parseInt(row.order_status, 10)) !== -1) {
                                    action_content += '<a href="' + base_url
                                        + 'index.php/admin_ret_purchase/purchase/edit/' + id
                                        + '" class="btn btn-warning" data-toggle="tooltip" '
                                        + 'title="Edit Purchase Order"><i class="fa fa-pencil"></i></a>';
                                }

                                return action_content;

                            }

                        },



                    ]



                });







            }



            $("div.overlay").css("display", "none");



        },



        error: function (error) {



            $("div.overlay").css("display", "none");



        }



    });



}



function send_karigar_sms(id_customer_order, mobile) {



    if (mobile != '') {



        my_Date = new Date();



        $("div.overlay").css("display", "block");



        $.ajax({



            url: base_url + "index.php/admin_ret_purchase/send_karigar_sms?nocache=" + my_Date.getUTCSeconds() + '' + my_Date.getUTCMinutes() + '' + my_Date.getUTCHours(),



            data: { 'mobile': mobile, 'id_customer_order': id_customer_order },



            type: "POST",



            async: false,



            dataType: 'json',



            success: function (data) {



                if (data.status) {



                    $('#order_delviery').prop('disabled', false);



                    $.toaster({ priority: 'success', title: 'Warning!', message: '' + "</br>" + data.message });



                    $("div.overlay").css("display", "none");



                    window.location.reload();



                } else {



                    $('#order_delviery').prop('disabled', false);



                    $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + data.message });



                }







            },



            error: function (error) {



                $("div.overlay").css("display", "none");



            }



        });



    }



    else {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Mobile Number Not Found" });



    }



}



