function get_purchase_entry(from_date, to_date) {



    $("div.overlay").css("display", "block");



    my_Date = new Date();



    $.ajax({



        url: base_url + "index.php/admin_ret_purchase/purchase/purchase_entry?nocache=" + my_Date.getUTCSeconds(),



        dataType: "JSON",



        type: "POST",



        data: { 'from_date': from_date, 'to_date': to_date },



        success: function (data) {



            var access = data.access;



            var list = data.list;



            var profile = data.profile;



            var currentDate = new Date();



            var formattedCurrentDate =

                currentDate.getDate().toString().padStart(2, '0') + '-' +

                (currentDate.getMonth() + 1).toString().padStart(2, '0') + '-' +

                currentDate.getFullYear();





            var oTable = $('#pur_entry_list').DataTable();



            oTable.clear().draw();



            if (list != null && list.length > 0) {



                oTable = $('#pur_entry_list').dataTable({



                    "bDestroy": true,



                    "bInfo": true,



                    "bFilter": true,



                    "bSort": true,



                    "ordering": false,



                    "dom": 'lBfrtip',



                    "buttons": ['excel', 'print'],



                    "tableTools": { "buttons": [{ "sExtends": "xls", "oSelectorOpts": { page: 'current' } }, { "sExtends": "pdf", "oSelectorOpts": { page: 'current' } }] },



                    "aaData": list,



                    "aoColumns": [



                        {



                            "mDataProp": function (row, type, val, meta) {



                                if (row.is_approved == "Approved") {



                                    chekbox = row.po_id;



                                }



                                else {



                                    if (row.bill_status == 1 && profile.allow_supplier_bill_approval == 1) {



                                        chekbox = '<input type="checkbox" class="po_id_for_approve" name="id_po[]" po_id="' + row.po_id + '" value="' + row.po_id + '" />' + '&nbsp;' + row.po_id;



                                    } else {



                                        chekbox = row.po_id;



                                    }



                                }



                                return chekbox;



                            }



                        },



                        { "mDataProp": "grn_ref_no" },



                        { "mDataProp": "po_date" },


                         {
                            "mDataProp": function (row, type, val, meta) {
                                // For input type="date", we need yyyy-mm-dd format
                                var dateValue = '';
                                if (row.po_delivery_date && row.po_delivery_date !== '0000-00-00' && row.po_delivery_date !== null) {
                                    dateValue = row.po_delivery_date; // Keep in yyyy-mm-dd format for input type="date"
                                }
                                // Create editable date input with dynamic ID
                                var inputField = '<input type="date" id="due_date' + row.po_id + '" class="form-control due-date-field" value="' + dateValue + '" style="width:150px; text-align:center;" data-po-id="' + row.po_id + '" readonly />';
                                return inputField;
                            }
                        },


                        { "mDataProp": "po_ref_no" },



                        { "mDataProp": "karigar" },



                        { "mDataProp": "category_name" },



                        { "mDataProp": "purity" },



                        { "mDataProp": "gross_wt" },



                        { "mDataProp": "tot_lwt" },



                        { "mDataProp": "tot_nwt" },



                        { "mDataProp": "tot_purchase_amt" },



                        { "mDataProp": "tot_purchase_wt" },

                        {
                            "mDataProp": function (row) {
                                let p = parseInt(row.purchase_type);
                                if (p === 1) return "Stock";
                                if (p === 2) return "Walkin";
                                if (p === 3) return "Expo";
                                return "-";
                            }
                        },


                        { "mDataProp": "grs_wt" },



                        { "mDataProp": "grn_net_wt" },



                        {
                            "mDataProp": function (row, type, val, meta) {

                                var grs_wt = parseFloat(row.grs_wt);

                                var gross_wt = parseFloat(row.gross_wt);

                                if (isNaN(grs_wt)) grs_wt = 0;

                                if (isNaN(gross_wt)) gross_wt = 0;

                                action_content = parseFloat(grs_wt - gross_wt).toFixed(3);

                                return action_content;

                            }

                        },



                        {

                            "mDataProp": function (row, type, val, meta) {

                                var grn_net_wt = parseFloat(row.grn_net_wt);

                                var tot_nwt = parseFloat(row.tot_nwt);

                                if (isNaN(grn_net_wt)) grn_net_wt = 0;

                                if (isNaN(tot_nwt)) tot_nwt = 0;

                                action_content = parseFloat(grn_net_wt - tot_nwt).toFixed(3);

                                return action_content;

                            }

                        },



                        { "mDataProp": "emp_name" },



                        //{ "mDataProp": "is_approved" },



                        {
                            "mDataProp": function (row, type, val, meta) {



                                if (row.bill_status == 2) {

                                    return 'Cancelled';

                                } else {

                                    return row.is_approved;

                                }

                            }



                        },



                        {
                            "mDataProp": function (row, type, val, meta) {



                                id = row.po_id;



                                let print_url = '';



                                edit_url = (access.edit == '1' ? base_url + 'index.php/admin_ret_purchase/purchase/purchase_add/' + id : '#');



                                delete_url = (access.delete == '1' ? '#' : '#');



                                delete_confirm = (access.delete == '1' ? '#confirm-delete' : '');



                                //if(row.purchase_type == 1) {



                                print_url = '<a href="' + base_url + 'index.php/admin_ret_purchase/purchase/job_receipt/' + id + '" target="_blank" class="btn btn-info btn-print" data-toggle="tooltip" title="" data-original-title="Customer Copy"><i class="fa fa-print"></i></a>';



                                //}



                                action_content = (row.approved_status == 0 && row.bill_status == 1 && access.edit == '1' ? '<a href="' + edit_url + '" class="btn btn-primary btn-edit"><i class="fa fa-edit" ></i></a>' : '') + print_url + ((row.po_date == formattedCurrentDate || profile.previous_bill_cancel == 1) && row.approved_status == 0 && row.bill_status == 1 && access.delete == '1' ? '<button class="btn btn-warning" onclick="po_cancel(' + id + ')"><i class="fa fa-close" ></i></button>' : '');



                                return action_content;



                            }



                        }



                    ],



                    "footerCallback": function (row, data, start, end, display) {

                        if (data.length > 0) {

                            var api = this.api(), data;

                            for (var i = 0; i <= data.length - 1; i++) {

                                var intVal = function (i) {

                                    return typeof i === 'string' ?

                                        i.replace(/[\$,]/g, '') * 1 :

                                        typeof i === 'number' ?

                                            i : 0;

                                };



                                $(api.column(0).footer()).html('Total');



                                gwt = api

                                    .column(7)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(7).footer()).html(money_format_india(parseFloat(gwt).toFixed(3)));



                                lwt = api

                                    .column(8)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(8).footer()).html(money_format_india(parseFloat(lwt).toFixed(3)));



                                nwt = api

                                    .column(9)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(9).footer()).html(money_format_india(parseFloat(nwt).toFixed(3)));



                                pur_amt = api

                                    .column(10)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(10).footer()).html(money_format_india(parseFloat(pur_amt).toFixed(2)));



                                pur_wt = api

                                    .column(11)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(11).footer()).html(money_format_india(parseFloat(pur_wt).toFixed(3)));



                                grn_wt = api

                                    .column(12)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(12).footer()).html(money_format_india(parseFloat(grn_wt).toFixed(3)));



                                $(api.column(13).footer()).html('');



                                var total_grn_wt = api

                                    .column(14)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(14).footer()).html(money_format_india(parseFloat(total_grn_wt).toFixed(3)));



                                var total_grn_nt = api

                                    .column(15)

                                    .data()

                                    .reduce(function (a, b) {

                                        return intVal(a) + intVal(b);

                                    }, 0);

                                $(api.column(15).footer()).html(money_format_india(parseFloat(total_grn_nt).toFixed(3)));



                                var total_diff_wt = parseFloat(total_grn_wt) - parseFloat(lwt);

                                $(api.column(16).footer()).html(money_format_india(parseFloat(total_diff_wt).toFixed(3)));



                                var total_nwt = api

                                    .column(10)
                                    .data()
                                    .reduce(function (a, b) {
                                        return intVal(a) + intVal(b);
                                    }, 0);

                                var total_diff_nwt = parseFloat(total_grn_nt) - parseFloat(total_nwt);

                                $(api.column(17).footer()).html(money_format_india(parseFloat(total_diff_nwt).toFixed(3)));







                            }



                        } else {



                            var api = this.api(), data;



                            $(api.column(13).footer()).html('');



                            $(api.column(11).footer()).html('');



                            $(api.column(12).footer()).html('');



                            $(api.column(14).footer()).html('');



                            $(api.column(15).footer()).html('');



                            $(api.column(16).footer()).html('');



                            $(api.column(6).footer()).html('');



                            $(api.column(7).footer()).html('');



                            $(api.column(8).footer()).html('');



                            $(api.column(9).footer()).html('');



                            $(api.column(10).footer()).html('');



                        }

                    }



                });







            }



            $("div.overlay").css("display", "none");



        },



        error: function (error) {



            $("div.overlay").css("display", "none");



        }



    });



}



