$('#tot_gwt,#tot_wastage_perc,#rate_per_gram,#tot_pcs,#tot_wastage_perc,#mc_value,#purchase_touch').on('keyup input change', function () {



    var stone_type = $('#select_product option:selected').attr('data-stone_type');

    if (stone_type == 2) // for diamond product

    {

        set_karigar_wise_wastage();

    }



    var tot_gwt = (isNaN($('#tot_gwt').val()) || $('#tot_gwt').val() == '' ? 0 : $('#tot_gwt').val());



    var tot_lwt = (isNaN($('#tot_lwt').val()) || $('#tot_lwt').val() == '' ? 0 : $('#tot_lwt').val());



    var other_metal_wt = (isNaN($('#other_metal_wt').val()) || $('#other_metal_wt').val() == '' ? 0 : $('#other_metal_wt').val());



    $('#tot_nwt').val(parseFloat(tot_gwt - tot_lwt).toFixed(3));







    var tot_netwt = parseFloat(tot_gwt - (tot_lwt + other_metal_wt)).toFixed(3);



    //var purity = parseFloat($("#select_purity option:selected").text());



    var purity = (isNaN($('#purchase_touch').val()) || $('#purchase_touch').val() == '' ? 0 : $('#purchase_touch').val());



    var wastage = (isNaN($('#tot_wastage_perc').val()) || $('#tot_wastage_perc').val() == '' ? 0 : $('#tot_wastage_perc').val());







    // Pure Weight Calculation based on Purity Type (999/995/9999)
    var purewt = parseFloat((parseFloat(tot_netwt) * (parseFloat(purity) + parseFloat(wastage))) / 100);

    // When purity 995/9999 is selected, adjust: pure_wt = base_pure_wt / fineness
    var purity_type = $('#purity_type').val();
    if (purity_type == '995') {
        purewt = purewt / 0.995;
    } else if (purity_type == '9999') {
        purewt = purewt / 0.9999;
    }

    purewt = purewt.toFixed(3);







    $('#tot_purewt').val(format(purewt).replace(/,/g, ''));







    calculate_purchase_item_cost();



});

// Purity Type (999/995) change handler - recalculate pure weight using event delegation
$(document).on('change', '#purity_type', function () {
    console.log('Purity type changed to:', $(this).val());
    var tot_gwt = (isNaN($('#tot_gwt').val()) || $('#tot_gwt').val() == '' ? 0 : parseFloat($('#tot_gwt').val()));
    var tot_lwt = (isNaN($('#tot_lwt').val()) || $('#tot_lwt').val() == '' ? 0 : parseFloat($('#tot_lwt').val()));
    var other_metal_wt = (isNaN($('#other_metal_wt').val()) || $('#other_metal_wt').val() == '' ? 0 : parseFloat($('#other_metal_wt').val()));
    var tot_netwt = parseFloat(tot_gwt - (tot_lwt + other_metal_wt)).toFixed(3);
    var purity = (isNaN($('#purchase_touch').val()) || $('#purchase_touch').val() == '' ? 0 : parseFloat($('#purchase_touch').val()));
    var wastage = (isNaN($('#tot_wastage_perc').val()) || $('#tot_wastage_perc').val() == '' ? 0 : parseFloat($('#tot_wastage_perc').val()));

    var purewt = parseFloat((parseFloat(tot_netwt) * (purity + wastage)) / 100);

    // When purity 995/9999 is selected, adjust: pure_wt = base_pure_wt / fineness
    var purity_type = $(this).val();
    if (purity_type == '995') {
        purewt = purewt / 0.995;
    } else if (purity_type == '9999') {
        purewt = purewt / 0.9999;
    }

    purewt = purewt.toFixed(3);
    console.log('New pure weight:', purewt);
    $('#tot_purewt').val(format(purewt).replace(/,/g, ''));
    calculate_purchase_item_cost();
});



