        + '<td style="text-align:right;"><input type="hidden" class="tot_purewt" name="order_item[tot_purewt][]" value="' + item.item_pure_wt + '"><input type="hidden" class="purity_type" name="order_item[purity_type][]" value="' + item.purity_type + '"><span style="text-align:right;">' + money_format_india(item.item_pure_wt) + '</span></td>'
