/**
 * Auto-calculate MC (Making Charges) for Approval Receipt flow.
 * When Approval Stock = YES, Rate Fixed = YES, and GRN type = Receipt (2),
 * MC is auto-calculated using:
 *   Step 1: MC% = Touch - Purity (numeric from ret_purity table)
 *   Step 2: MC Value = MC% * Rate Per Gram (board rate)
 *   Step 3: Final MC = MC Value + 5% (static markup, NOT GST)
 * The MC field is disabled and shows the final value (with 5% markup).
 * IMPORTANT: This mc_value should NOT have GST applied on it during
 * total amount calculation — it is already the final MC value.
 * Returns true if auto-MC was applied, false otherwise.
 */
function auto_calculate_mc_for_approval_receipt() {
    if (ctrl_page[1] != 'purchase' || ctrl_page[2] != 'purchase_add') return false;

    // Determine GRN type from activeGRNS
    var current_grn_type = '';
    $.each(activeGRNS, function (g, val) {
        if (val.grn_id == $('#select_grn').val()) {
            current_grn_type = val.grn_type;
        }
    });

    // Auto-MC triggers only for GRN type 4 (JB)
    if (current_grn_type == 4) {
        // Get the numeric purity value from purityDetails based on selected purity ID
        var selected_purity_id = $('#select_purity').val();
        var purity_numeric_value = 0;

        $.each(purityDetails, function (k, p) {
            if (p.id_purity == selected_purity_id) {
                purity_numeric_value = parseFloat(p.purity);
            }
        });

        // Step 1: MC% = Touch - Purity
        var touch_value = parseFloat($('#purchase_touch').val()) || 0;
        var mc_percentage = touch_value - purity_numeric_value;
        if (mc_percentage < 0) mc_percentage = 0;

        // Step 2: MC Value = MC% * Rate Per Gram (board rate)
        var board_rate = parseFloat($('#rate_per_gram').val()) || 0;
        var mc_value_raw = parseFloat(mc_percentage/100 * board_rate).toFixed(2);

        // Step 3: Final MC = MC Value + 5% (static markup, NOT GST)
        var mc_with_markup = parseFloat(mc_value_raw).toFixed(2);

        // Set auto-calculated MC (with 5% markup) and disable the field
        // This value should NOT have GST applied again during total calculation
        $('#mc_value').val(mc_with_markup);
        $('#mc_value').prop('disabled', true);

        return true; // Auto-MC is active
    }

    return false; // Auto-MC not active
}


