function get_purchase_order_payment_list(from_date, to_date) {



    $("div.overlay").css("display", "block");



    my_Date = new Date();

    var currentDate = new Date();

    var formattedCurrentDate =

        currentDate.getDate().toString().padStart(2, '0') + '-' +

        (currentDate.getMonth() + 1).toString().padStart(2, '0') + '-' +

        currentDate.getFullYear();

    $.ajax({



        url: base_url + "index.php/admin_ret_purchase/supplier_po_payment/ajax?nocache=" + my_Date.getUTCSeconds(),



        dataType: "JSON",



        data: { 'from_date': from_date, 'to_date': to_date },



        type: "POST",



        success: function (data) {



            var list = data.list;



            var access = data.access;



            var oTable = $('#payment_list').DataTable();



            oTable.clear().draw();



            if (list != null && list.length > 0) {



                oTable = $('#payment_list').dataTable({



                    "bDestroy": true,



                    "bInfo": true,



                    "bFilter": true,



                    "bSort": true,



                    "order": [[0, "desc"]],



                    "dom": 'lBfrtip',



                    "buttons": ['excel', 'print'],



                    "tableTools": { "buttons": [{ "sExtends": "xls", "oSelectorOpts": { page: 'current' } }, { "sExtends": "pdf", "oSelectorOpts": { page: 'current' } }] },



                    "aaData": list,



                    "aoColumns": [



                        { "mDataProp": "pay_id" },



                        { "mDataProp": "pay_date" },



                        { "mDataProp": "pay_refno" },



                        { "mDataProp": "karigar_name" },



                        { "mDataProp": "pay_amt" },



                        { "mDataProp": "bill_type" },



                        { "mDataProp": "status" },







                        {
                            "mDataProp": function (row, type, val, meta) {



                                id = row.pay_id;



                                edit_target = (access.edit == '0' ? "" : "#confirm-edit");



                                print_url = (base_url + 'index.php/admin_ret_purchase/supplier_po_payment/paymentacknolodgement/' + id);

                                cheque_url = (row.has_cheque > 0 ? '<a href="' + base_url + 'index.php/admin_ret_purchase/supplier_po_payment/print_cheque/' + id + '" target="_blank" class="btn btn-success" data-toggle="tooltip" title="Print Cheque"><i class="fa fa-money"></i></a>' : '');

                                cancel_url = (row.pay_status == 1 ? '<button onclick="confirm_bill_cancel(' + id + ')" class="btn btn-warning" data-toggle="tooltip" title="Cancel Payment"><i class="fa fa-close"></i></button>' : '');

                                edit_url = ((row.pay_date == row.day_close_date) && access.edit == '1' ? '<a href="' + base_url + 'index.php/admin_ret_purchase/supplier_po_payment/edit/' + id + '" class="btn btn-primary btn-edit"><i class="fa fa-edit" ></i></a>' : '');



                                delete_url = ((row.pay_date == row.day_close_date) && access.delete == '1' ? '<button onclick="confirm_bill_cancel(' + id + ')" class="btn btn-danger"> <i class="fa fa-close" ></i></button>' : '');





                                // PUR-CR04: Conditional cheque print + dual-print on Payment Copy click
                                cheque_print_url = (base_url + 'index.php/admin_ret_purchase/supplier_po_payment/print_cheque/' + id);
                                cheque_btn = (parseInt(row.has_cheque) > 0 ? '<a href="' + cheque_print_url + '" target="_blank" class="btn btn-success" data-toggle="tooltip" title="Cheque Print"><i class="fa fa-money" ></i></a>' : '');
                                print_btn = '<a href="javascript:void(0);" onclick="printPaymentCopy(\'' + print_url + '\', \'' + cheque_print_url + '\', ' + parseInt(row.has_cheque) + ')" class="btn btn-info" data-toggle="tooltip" title="Payment Copy"><i class="fa fa-print" ></i></a>';
                                action_content = (row.pay_status == 1 ? edit_url + print_btn + cheque_btn + delete_url : '-');



                                return action_content;



                            }



                        }







                    ]



                });







            }



            $("div.overlay").css("display", "none");



        },



        error: function (error) {



            $("div.overlay").css("display", "none");



        }



    });



}



