$('#add_image').on('click', function () {

    // PUR-CLT02: Clear stale image data before opening modal
    img_resource = [];
    total_files = [];
    localStorage.removeItem('img_details');
    $('#order_images').empty();
    $('#order_images_new').val('');
    $('#add_image_preview').empty(); // PUR-CLT02: Clear previous preview
    $('#add_image').text('Add Image'); // PUR-CLT02: Reset button text

    $('#imageModal_new').modal('show');



});



$("#update_img_new").on('click', function () {



    var final_file = [];



    var retrive_file = [];



    let image_details = localStorage.getItem('img_details');



    console.log(image_details);



    localStorage.removeItem('img_details');



    $('#order_iamges').val(image_details);



    $('#imageModal_new').modal('toggle');

    // PUR-CLT02: Show image preview thumbnails near the Add Image button
    $('#add_image_preview').empty();
    if (image_details && image_details !== 'null' && image_details !== '[]') {
        var images = JSON.parse(image_details);
        $.each(images, function(index, item) {
            if (item && item.src) {
                $('#add_image_preview').append(
                    '<img src="' + item.src + '" style="width:50px; height:50px; object-fit:cover; border:1px solid #ddd; border-radius:3px;" />'
                );
            }
        });
        // Update button text to show count
        $('#add_image').html('<i class="fa fa-image"></i> Add Image (' + images.length + ')');
    } else {
        $('#add_image').text('Add Image');
    }

});



