$('#select_grn').on('change', function () {



    var currentgrn = this.value;



    $("#select_karigar").prop("disabled", false);



    $('#grn_item_details_preview > tbdoy').empty();



    var trHtml = '';



    if (currentgrn != '') {



        $("div.overlay").css("display", "block");



        var url = base_url + "index.php/admin_ret_purchase/purchase/grncatdetailsbygrnid?nocache=" + my_Date.getUTCSeconds();



        my_Date = new Date();



        $.ajax({



            url: url,



            data: { "grnId": currentgrn, "cat_type": $("input[type='radio'][name='order[po_type]']:checked").val() },



            type: "POST",



            dataType: "JSON",



            success: function (data) {







                $.each(activeGRNS, function (gkey, gitem) {



                    if (parseInt(gitem.grn_id) === parseInt(currentgrn)) {



                        $("#select_karigar").select2("val", gitem.grn_karigar_id);



                        $("#select_karigar").prop("disabled", true);



                        $("#id_karigar").val(gitem.grn_karigar_id);



                        $("#purchase_type").val(gitem.purchase_type);



                        $(".po_irnno").val(gitem.grn_irnno != null ? gitem.grn_irnno : "");



                        $(".ewaybillno").val(gitem.grn_ewaybillno);



                        $(".po_ref_no").val(gitem.grn_supplier_ref_no);



                        $(".po_ref_date").val(gitem.grn_ref_date != null ? gitem.grn_ref_date : "");



                        $('#despatch_through').select2("val", gitem.grn_despatch_through);



                        var tds_purchase_limit = $('#tds_purchase_limit').val();



                        var item_cost = $('#opening_balance').val();



                        var total_balance_amount = item_cost;



                        if (tds_purchase_limit >= total_balance_amount) {

                            $('#bal_tds_percent').val(gitem.grn_pay_tds_percent);

                        }

                        else {

                            $('#bal_tds_percent').val(0);

                        }



                        // $('#po_tds_percent').val(gitem.grn_pay_tds_percent);



                        $('#po_tcs_percent').val(gitem.grn_tcs_percent);



                        $('#other_charges_taxable_amount').val(parseFloat(gitem.charges_amount).toFixed(2));



                        $('#charges_tds_percent').val(gitem.grn_other_charges_tds_percent);



                        $('#other_charges_tax').val(gitem.charges_tax);



                        $('#po_discount').val(gitem.grn_discount);

                        if (gitem.grn_type == 2) {
                            $('#approval_stock_yes').prop('checked', true);
                            $('#approval_stock_no').prop('checked', false);
                            $('#is_rate_fixed_no').prop('checked', true);
                            $('.is_rate_fixed').prop('disabled', false);
                            $('#mc_value').prop('disabled', false);
                        } else if (gitem.grn_type == 4) {
                            // JB: Approval Stock = No, Rate Fixed = Yes (disabled), MC disabled
                            $('#approval_stock_no').prop('checked', true);
                            $('#approval_stock_yes').prop('checked', false);
                            $('#is_rate_fixed_yes').prop('checked', true);
                            $('.is_rate_fixed').prop('disabled', true);
                            $('#mc_value').prop('disabled', true);
                        } else {
                            $('#approval_stock_no').prop('checked', true);
                            $('#approval_stock_yes').prop('checked', false);
                            $('#is_rate_fixed_yes').prop('checked', true);
                            $('.is_rate_fixed').prop('disabled', false);
                            $('#mc_value').prop('disabled', false);
                        }
                        $('input[name="order[is_suspense_stock]"]').prop("disabled", true);







                        console.log(data);



                        $('#grn_item_details_preview > tbody').empty();



                        $.each(data, function (key, val) {



                            trHtml += '<tr>'



                                + '<td>' + val.catname + '</td>'



                                + '<td class="grn_pcs">' + val.no_of_pcs + '</td>'



                                + '<td class="grn_gwt" style="text-align:right;">' + val.gross_wt + '</td>'



                                + '<td class="grn_lwt" style="text-align:right;">' + val.grn_less_wt + '</td>'



                                + '<td class="grn_nwt" style="text-align:right;">' + val.grn_net_wt + '</td>'



                                + '<td class="grn_diawt" style="text-align:right;">' + parseFloat(val.dia_wt).toFixed(3) + '</td>'



                                + '<td class="grn_rate" style="text-align:right;">' + val.rate_per_grm + '</td>'



                                + '<td class="grn_amt" style="text-align:right;">' + val.item_cost + '</td>'



                                + '</tr>';



                        });







                    }



                });



                console.log(trHtml);



                if (ctrl_page[2] == 'purchase_add' && ctrl_page[3] == undefined) {

                    if (data.length > 0) {

                        let grn_tds_percent = data[0].grn_tds_percent;

                        $(".po_tds_percent").val(parseFloat(grn_tds_percent).toFixed(2));

                    } else {

                        $(".po_tds_percent").val(0);

                    }

                }



                $('#select_category option').remove();



                $('#grn_item_details_preview > tbody').append(trHtml);



                $.each(data, function (key, item) {







                    $("#select_category").append(



                        $("<option></option>")



                            .attr("value", item.cat_id)



                            .attr("data-cattype", item.cat_type)



                            .text(item.catname)



                    );



                });



                $('#select_category').select2({



                    placeholder: "Category",



                    allowClear: true



                });



                $("#select_category").select2("val", "");



                $("div.overlay").css("display", "none");



                grncatdetails = data;



                calculate_purchase_item_details();



            },



            error: function (error) {



                $("div.overlay").css("display", "none");



            }



        });



    }



});





function Edit_ItemDetails(curRow) {
    // Store values from the row BEFORE removing it
    var edit_po_order_no = curRow.find('.po_order_no').val();
    var edit_category = curRow.find('.id_category').val();
    var edit_purity = curRow.find('.id_purity').val();
    var edit_product = curRow.find('.id_product').val();
    var edit_design = curRow.find('.id_design').val();
    var edit_sub_design = curRow.find('.id_sub_design').val();
    var edit_ratecaltype = curRow.find('.ratecaltype').val();
    var edit_tot_pcs = curRow.find('.tot_pcs').val();
    var edit_tot_gwt = curRow.find('.tot_gwt').val();
    var edit_tot_lwt = curRow.find('.tot_lwt').val();
    var edit_tot_nwt = curRow.find('.tot_nwt').val();
    var edit_tot_purewt = curRow.find('.tot_purewt').val();
    var edit_stone_details = curRow.find('.stone_details').val();
    var edit_stone_price = curRow.find('.stone_price').val();
    var edit_mc_type = curRow.find('.mc_type').val();
    var edit_mc_value = curRow.find('.mc_value').val();
    var edit_tot_wastage_perc = curRow.find('.tot_wastage_perc').val();
    var edit_other_metal_amt = curRow.find('.other_metal_amt').val();
    var edit_other_metal_details = curRow.find('.other_metal_details').val();
    var edit_other_chrg_details = curRow.find('.other_chrg_details').val();
    var edit_rate_per_gram = curRow.find('.rate_per_gram').val();
    var edit_item_cost = curRow.find('.item_cost').val();
    var edit_po_item_id = curRow.find('.po_item_id').val();
    var edit_item_remarks = curRow.find('.item_remarks').val();
    var edit_purchase_touch = curRow.find('.purchase_touch').val();
    var edit_pur_calc_type = curRow.find('.pur_calc_type').val();
    var edit_calculation_based_on = curRow.find('.calculation_based_on').val();
    var edit_gst_bill_rate_basis = curRow.find('.gst_bill_rate_basis').val();

    curRow.remove();

    // Set PO No
    $('#select_po_no').select2("val", edit_po_order_no);

    // Set hidden fields FIRST - these are read by the AJAX success callbacks
    // for auto-selecting the correct values after options are loaded
    $('#id_purity').val(edit_purity);
    $('#pro_id').val(edit_product);
    $('#design_id').val(edit_design);
    $('#sub_design_id').val(edit_sub_design);

    $('#purchase_mode').val(edit_ratecaltype);

    // Set non-dropdown form fields
    $('#tot_pcs').val(edit_tot_pcs);
    $('#tot_gwt').val(edit_tot_gwt);
    $('#tot_lwt').val(edit_tot_lwt);
    $('#tot_nwt').val(edit_tot_nwt);
    $('#tot_purewt').val(edit_tot_purewt);
    $('#stone_details').val(edit_stone_details);
    $('#stone_price').val(edit_stone_price);
    $('#mc_type').val(edit_mc_type);
    $('#mc_value').val(edit_mc_value);
    $('#tot_wastage_perc').val(edit_tot_wastage_perc);
    $('#other_metal_amount').val(edit_other_metal_amt);
    $('#other_metal_details').val(edit_other_metal_details);
    $('#other_charges_details').val(edit_other_chrg_details);
    $('#rate_per_gram').val(edit_rate_per_gram);
    $('#total_payable_amt').val(edit_item_cost);
    $('#po_item_id').val(edit_po_item_id);
    $('#item_remarks').val(edit_item_remarks);
    $('#purchase_touch').val(edit_purchase_touch);
    $('#karigar_calc_type').val(edit_pur_calc_type);
    $('#calculation_based_on').val(edit_calculation_based_on).trigger('change');

    // PUR-2607021534: Restore GST Bill Rate Basis (PureWt/Grswt/Netwt) — like the add process sets it
    var saved_rate_basis = (edit_gst_bill_rate_basis != '' && edit_gst_bill_rate_basis != undefined) ? edit_gst_bill_rate_basis : '0';
    $('#gst_bill_rate_basis').val(saved_rate_basis).trigger('change');
    // END PUR-2607021534

    // Parse stone/metal/charge details for modals
    modalStoneDetail = (edit_stone_details != '' && edit_stone_details != undefined ? JSON.parse(edit_stone_details) : '');
    modalOthermetal = (edit_other_metal_details != '' && edit_other_metal_details != undefined ? JSON.parse(edit_other_metal_details) : '');
    modalChargeDetail = (edit_other_chrg_details != '' && edit_other_chrg_details != undefined ? JSON.parse(edit_other_chrg_details) : '');

    if ($('#supplier_bill_entry_calc').val() == 1) {
        set_karigar_wise_wastage();
    }

    // Set category (it already has options from GRN selection)
    $('#select_category').select2("val", edit_category);

    // Load purity options based on category (auto-selects via #id_purity hidden field)
    get_cat_purity();

    // Load product options based on category, then chain design and sub-design loading
    $('#select_product option').remove();
    $(".overlay").css("display", "block");
    my_Date = new Date();
    $.ajax({
        type: 'POST',
        data: { 'id_ret_category': edit_category },
        url: base_url + "index.php/admin_ret_catalog/get_ActiveProducts/?nocache=" + my_Date.getUTCSeconds(),
        dataType: 'json',
        success: function (data) {
            $.each(data, function (key, item) {
                $('#select_product').append(
                    $("<option></option>")
                        .attr("value", item.pro_id)
                        .text(item.product_name)
                        .attr("data-purmode", item.purchase_mode)
                        .attr("data-tax_type", item.tax_type)
                        .attr("data-stone_type", item.stone_type)
                        .attr("data-calculation_based_on", item.calculation_based_on)
                );
            });
            $('#select_product').select2({ placeholder: "Product", allowClear: true });
            if ($('#select_product').length && edit_product != '' && edit_product != undefined) {
                $('#select_product').select2("val", edit_product);
            }
            $("div.overlay").css("display", "none");

            // After product is set, load designs
            if (edit_product != '' && edit_product != undefined) {
                $('#select_design option').remove();
                $(".overlay").css('display', 'block');
                $.ajax({
                    type: 'POST',
                    url: base_url + 'index.php/admin_ret_catalog/get_active_design_products',
                    dataType: 'json',
                    data: { 'id_product': edit_product },
                    success: function (desData) {
                        $.each(desData, function (key, item) {
                            $('#select_design').append(
                                $("<option></option>")
                                    .attr("value", item.design_no)
                                    .text(item.design_name)
                            );
                        });
                        $("#select_design").select2({ placeholder: "Design", allowClear: true });
                        if (edit_design != '' && edit_design != undefined && edit_design > 0) {
                            $("#select_design").select2("val", edit_design);
                        }
                        $(".overlay").css("display", "none");

                        // After design is set, load sub-designs
                        if (edit_design != '' && edit_design != undefined && edit_design > 0) {
                            $('#select_sub_design option').remove();
                            $(".overlay").css('display', 'block');
                            $.ajax({
                                type: 'POST',
                                url: base_url + 'index.php/admin_ret_catalog/get_ActiveSubDesigns',
                                dataType: 'json',
                                data: { 'id_product': edit_product, 'design_no': edit_design },
                                success: function (subDesData) {
                                    $.each(subDesData, function (key, item) {
                                        $('#select_sub_design').append(
                                            $("<option></option>")
                                                .attr("value", item.id_sub_design)
                                                .text(item.sub_design_name)
                                        );
                                    });
                                    $("#select_sub_design").select2({ placeholder: "Sub Design", allowClear: true });
                                    if (edit_sub_design != '' && edit_sub_design != undefined && edit_sub_design > 0) {
                                        $("#select_sub_design").select2("val", edit_sub_design);
                                    }
                                    $(".overlay").css("display", "none");
                                }
                            });
                        }
                    }
                });
            }
        }
    });

    calculate_purchase_order_item_total();

    setTimeout(function () { calculate_purchase_item_cost() }, 3000);
}


