$('#gst_no').on('change', function () {



    var reggst = /^([0][1-9]|[1-2][0-9]|[3][0-7])([a-zA-Z]{5}[0-9]{4}[a-zA-Z]{1}[1-9a-zA-Z]{1}[zZ]{1}[0-9])+$/;



    if (!reggst.test($('#gst_no').val())) {



        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>" + 'Enter the Valid GST No..' });



        $('#gst_no').val('');



        return false;



    }



});



