$('.src_wt,.src_amt,.src_rate,.charges_amount,.src_weight,.charges_amt').on('keyup', function () {
    var src_type = $("input[name='supplier_rate_cut[rate_cut_type]']:checked").val();
    var is_against_po = $('#issue_against_po_bills').val();

    var balance_wt = parseFloat($('#availablepurebalance').val()) || 0;
    var balance_wt_type = parseFloat($('#wt_balance_type').val()) || 0;
    var balance_amt = parseFloat($('#availableamtbalance').val()) || 0;

    var entered_charges = parseFloat($('.charges_amount').val()) || 0;
    var entered_weight = parseFloat($('.src_weight').val()) || 0;

    if (is_against_po == 1) {
        if (src_type == 1) { // Amount based conversion
            if (entered_charges > balance_amt) {
                $.toaster({ priority: 'danger', title: 'Warning!', message: '</br>Entered amount exceeds balance amount' });
                $('.charges_amount').val('').focus();
                $('#src_weight').val(''); // Resulting weight for type 1
                calculation_supplier_rate_cut();
                return false;
            }
        } 
        else if (src_type == 2) { // Weight based conversion
            if (entered_weight > balance_wt && balance_wt_type == 2) {
                $.toaster({ priority: 'danger', title: 'Warning!', message: '</br>Entered weight exceeds balance pure weight' });
                $('.src_weight').val('').focus();
                calculation_supplier_rate_cut();
                return false;
            }

            // Calculation to get total bill amount for secondary check
            calculation_supplier_rate_cut();
            // var total_bill_amt = parseFloat($('#total_bill_amount').val()) || 0;
            // if (total_bill_amt > balance_amt && balance_amt > 0) {
            //     $.toaster({ priority: 'danger', title: 'Warning!', message: '</br>Total bill amount exceeds balance amount' });
            //     $('.src_weight').val('').focus();
            //     calculation_supplier_rate_cut();
            //     return false;
            // }
        }
    }

    calculation_supplier_rate_cut();
});



function calculation_supplier_rate_cut() {



    $('#supplier_rate_cut_submit').prop('disabled', false);



    var src_type = $("input[name='supplier_rate_cut[rate_cut_type]']:checked").val();//1-Normal Conversion , 2-Conver to bill



    var convert_to = $("input[name='supplier_rate_cut[convert_to]']:checked").val(); //1-Bill,2-Receipt



    var igst_cost = 0;



    var sgst_cost = 0;



    var cgst_cost = 0;







    var cmp_country = $('#cmp_country').val();



    var cmp_state = $('#cmp_state').val();



    var supplier_country = '';



    var supplier_state = '';







    $.each(karigar_details, function (key, val) {



        if (val.id_karigar == $('#select_karigar').val()) {



            supplier_country = val.id_country;



            supplier_state = val.id_state;



        }



    });







    if (convert_to == 1) {



        var tax_percentage = 3;



    }



    else if (convert_to == 2) {



        var tax_percentage = 5;



    }



    else if (convert_to == 3) {



        var tax_percentage = 0.25;



    }



    else if (convert_to == 4) {



        var tax_percentage = 1.25;



    }



    else if (convert_to == 5) { // Approval â€” GST 3%



        var tax_percentage = 3;



    }



    else {



        var tax_percentage = 3;



    }



    if (src_type == 1) {



        var total_amount = parseFloat($('.charges_amount').val()).toFixed(2);







    }



    else if (src_type == 2) {



        // Guard all inputs — prevent NaN from empty or cleared fields
        var charges_amount = parseFloat($('.charges_amount').val()) || 0;



        var src_weight = parseFloat($('.src_weight').val()) || 0;



        var src_rate = parseFloat($('.src_rate').val()) || 0;



        // Rate entered by user already includes GST — back-calculate taxable amount
        var gross_amount = parseFloat((src_weight * src_rate) + charges_amount).toFixed(2);



        var divisor = (tax_percentage > 0) ? (1 + tax_percentage / 100) : 1;

        var taxable_amount = parseFloat(gross_amount / divisor).toFixed(2);



        var tax_amount = parseFloat(gross_amount - taxable_amount).toFixed(2);



        var total_amount = gross_amount; // no addition needed — rate was already inclusive



        if (cmp_country == supplier_country) {



            if (cmp_state == supplier_state) {



                sgst_cost = parseFloat(tax_amount / 2).toFixed(2);



                cgst_cost = parseFloat(tax_amount / 2).toFixed(2);



            }



        } else {



            igst_cost = tax_amount;



        }



    }



    else if (src_type == 3) { // Amount to Pure â€” weight only, no GST



        var charges_amount = parseFloat($('.charges_amount').val()) || 0;



        var src_rate = parseFloat($('.src_rate').val()) || 0;



        var weight = (src_rate > 0) ? parseFloat(charges_amount / src_rate).toFixed(3) : 0;



        $('#src_weight').val(weight); // Set calculated weight into type1_wt field



        var taxable_amount = 0;
        var tax_amount = 0;
        var total_amount = parseFloat(charges_amount).toFixed(2);



    }


    var is_tds = $('#is_tds').is(':checked');
    var tds_percent = parseFloat($('#tds_percent').val()) || 0;
    var tds_tax_value = 0;
    if (is_tds && tds_percent > 0) {
        tds_tax_value = parseFloat(parseFloat(taxable_amount) * tds_percent / 100).toFixed(2);
    }
    $('#tds_tax_value').val(tds_tax_value);
    $('#tds_amount_display').html(tds_tax_value);
    if (is_tds && tds_tax_value > 0) {
        total_amount = (parseFloat(total_amount) - parseFloat(tds_tax_value)).toFixed(2);
    }

    round_of_val = total_amount;



    tot_cost = parseFloat(Math.round(total_amount)).toFixed(2);



    round_of_amt = parseFloat(tot_cost - round_of_val).toFixed(2);







    $('#taxable_amt').val(taxable_amount);



    $('#tax_amount').val(tax_amount);



    $('#total_bill_amount').val(tot_cost);



    $('#tax_percentage').val(tax_percentage);



    $('#round_of_amt').val(round_of_amt);



    $('#sgst_cost').val(sgst_cost);



    $('#cgst_cost').val(cgst_cost);



    $('#igst_cost').val(igst_cost);



    $('.tax_perc').html(tax_percentage + '%');



    if (src_type == 1) {



        calculate_supplier_rate_cut_payment_cost();



    }







}



function calculate_supplier_rate_cut_payment_cost() {
    var bal_amount = 0;
    var total_amount = 0;
    var receive_amount = ($('.total_bill_amount ').val() != '' ? $('.total_bill_amount ').val() : 0);
    var cash_amount = ($('.cash_amount').val() != '' ? $('.cash_amount').val() : 0);
    var net_banking_pay = ($('#tot_net_banking_amt').html() != '' ? $('#tot_net_banking_amt').html() : 0);
    var cheque_amount_pay = ($('#cheque_payment').html() != '' ? $('#cheque_payment').html() : 0);

    if (receive_amount > 0) {
        total_amount = parseFloat(parseFloat(net_banking_pay) + parseFloat(cash_amount) + parseFloat(cheque_amount_pay)).toFixed(2);
        bal_amount = parseFloat(parseFloat(receive_amount) - parseFloat(total_amount)).toFixed(2);

        if (bal_amount == 0) {
            $('#supplier_rate_cut_submit').prop('disabled', false);
        } else {
            $('#supplier_rate_cut_submit').prop('disabled', true);
        }
    } else {
        total_amount = parseFloat(parseFloat(net_banking_pay) + parseFloat(cash_amount) + parseFloat(cheque_amount_pay)).toFixed(2);
        bal_amount = parseFloat(0 - parseFloat(total_amount)).toFixed(2);
        $('#supplier_rate_cut_submit').prop('disabled', true);
    }
    
    $('#total_pay_amount').html(money_format_india(total_amount));
    $('#bal_amount').html(money_format_india(bal_amount));
}



