function get_qcissuedDetails() {



    my_Date = new Date();



    $.ajax({



        url: base_url + "index.php/admin_ret_purchase/qc_issue_receipt/qcIssuedEdit",



        data: ({ 'id_qc_issue': ctrl_page[3] }),



        type: "POST",



        dataType: "JSON",



        cache: false,



        success: function (data) {



            $('#select_po_ref_no').select2("val", data[0].po_id);



            $('#select_po_ref_no').prop('disabled', true);



            $('#emp_select').select2("val", (data[0].id_emp));



            $('#qc_process_id').val(data[0].qc_process_id);



            $('#item_detail tbody').empty();



            var rowExists = false;



            var trHtml = '';



            $.each(data, function (key, items) {



                $('#item_detail > tbody tr').each(function (bidx, brow) {



                    curRow = $(this);



                    if (curRow.find('.po_item_id').val() == items.po_item_id) {



                        rowExists = true;



                        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Item Already Exists.." });



                    }



                });



                if (!rowExists) {



                    var stone_details = [];



                    var stone_pcs = 0;



                    var stone_wt = 0;







                    $.each(items.stone_details, function (k, stnval) {



                        stone_pcs += parseFloat(stnval.po_stone_pcs);



                        $.each(uom_details, function (key, item) {



                            if (item.uom_id == stnval.po_stone_uom && stnval.is_apply_in_lwt == 1) {



                                if (((item.uom_short_code).toLowerCase() == 'ct') && (item.divided_by_value != null && item.divided_by_value != '')) //For Carat Need to convert into gram



                                {



                                    stone_wt += parseFloat(parseFloat(stnval.stone_wt) / parseFloat(item.divided_by_value));



                                } else {







                                    stone_wt += parseFloat(stnval.stone_wt);



                                }



                            }



                        });



                        stone_details.push({



                            'po_st_id': stnval.po_st_id,



                            'show_in_lwt': stnval.is_apply_in_lwt,



                            'stones_type': stnval.stone_type,



                            'stone_uom_id': stnval.po_stone_uom,



                            'stone_id': stnval.po_stone_id,



                            'stone_pcs': stnval.stone_pcs,



                            'stone_wt': stnval.stone_wt,



                            'stone_cal_type': stnval.po_stone_calc_based_on,



                            'stone_price': stnval.po_stone_amount,



                            'stone_rate': stnval.po_stone_rate,



                            'stone_quality_id': stnval.po_quality_id,



                            'bal_act_stone_pcs': stnval.bal_stn_pcs,



                            'bal_act_stone_wt': stnval.bal_stn_wt,



                        });



                    });



                    var blc_pcs_for_issue = 0;



                    var blc_gwt_for_issue = 0;



                    var blc_nwt_for_issue = 0;



                    $.each(items.blc_details, function (k, val) {



                        blc_pcs_for_issue += parseFloat(val.blc_qcissued_pcs);



                        blc_gwt_for_issue += parseFloat(val.blc_qcissued_gwt);



                        blc_nwt_for_issue += parseFloat(val.blc_qcissued_nwt);



                    })







                    var id = parseFloat($('#item_detail > tbody > tr').length + 1);



                    // blc_pcs_for_issue (from getBalanceQcIssueDetails, which already excludes this
                    // qc_process_id) already IS the full ceiling for this row, including room for its
                    // own current value — it is used directly as .act_pcs one line below. Adding
                    // items.issue_pcs on top double-counts and made a genuine 1-pc line sum to 2,
                    // so the lock never engaged; fixed to compare blc_pcs_for_issue alone.
                    var _isOrnamentItem = (items.cat_type == 1);

                    var _singlePcsLock = ($('#restrict_partial_wt_single_pcs').val() == 1 && parseFloat(blc_pcs_for_issue) === 1 && _isOrnamentItem);



                    trHtml = '<tr id="' + id + '">'



                        + '<td><input type="checkbox" class="qc_item_select" name="qc_item_select[]" value="1" checked/><input type="hidden" class="po_item_id" name="po_item_id[]" value="' + items.po_item_id + '" /><input type="hidden" class="is_single_pcs" value="' + (_singlePcsLock ? 1 : 0) + '" /><input type="hidden" class="is_ornament_item" value="' + (_isOrnamentItem ? 1 : 0) + '" />' + items.po_ref_no + '</td>'







                        + '<td>' + items.karigar + '</td>'







                        + '<td>' + items.product_name + '</td>'







                        + '<td>' + items.design_name + '</td>'







                        + '<td>' + items.sub_design_name + '</td>'







                        + '<td><input type="number" class="form-control qc_issue_pcs" style="text-align:right;" value="' + items.issue_pcs + '"' + (_singlePcsLock ? ' readonly' : '') + '><input type="hidden" class="act_pcs" value="' + blc_pcs_for_issue + '">Avail Pcs :' + blc_pcs_for_issue + '</td>'







                        + '<td><input type="number" class="form-control qc_issue_gross_wt" style="text-align:right;" value="' + items.issue_gwt + '"' + (_singlePcsLock ? ' readonly' : '') + '><input type="hidden" class="act_gwt" value="' + blc_gwt_for_issue + '">' + blc_gwt_for_issue + '</td>'



                        /*+'<td><input type="number" class="form-control qc_issue_less_wt" value="'+items.less_wt+'">'+items.less_wt+'</td>'*/







                        + '<td><div class="form-group"><div class="input-group "><input class="form-control custom-inp add_less_wt" style="text-align:right;" value="' + parseFloat(stone_wt).toFixed(3) + '" onClick="create_new_empty_qc_issue_stone_item($(this).closest(\'tr\'));"  type="number" name="item[less_wt][]" step="any" readonly /><span class="input-group-addon input-sm add_tag_lwt" onClick="create_new_empty_qc_issue_stone_item($(this).closest(\'tr\'));">+</span></div><input type="hidden" class="stone_details" value=' + JSON.stringify(stone_details) + '><input type="hidden" class="qc_issue_less_wt" value="' + parseFloat(stone_wt).toFixed(3) + '"></div></td>'











                        + '<td><input type="number" class="form-control qc_issue_net_wt" style="text-align:right;" value="' + items.issue_nwt + '" disabled><input type="hidden" class="act_nwt" value="' + blc_nwt_for_issue + '">' + blc_nwt_for_issue + '</td>'







                        + '<td><a href="#" onClick="remove_qc_item($(this).closest(\'tr\').remove());" class="btn btn-danger btn-del"><i class="fa fa-trash"></i></a></td>'







                        + '</tr>';



                    if ($('#item_detail > tbody  > tr').length > 0) {



                        $('#item_detail > tbody > tr:first').before(trHtml);



                    } else {



                        $('#item_detail tbody').append(trHtml);



                    }







                }



            });



            calculate_qu_issue_row_details();



            $(".overlay").css("display", "none");



        },



        error: function (error) {



        }



    });







}



