// Open cancel modal for smith/company opening balance
function confirm_opbal_cancel(op_bal_id) {
    $('#id_op_bal_cancel').val(op_bal_id);
    $('#op_bal_cancel_remark').val('');
    $('#op_bal_cancel_confirm').prop('disabled', true);
    $('#confirm-opbal-cancel').modal('show');
}

// Enable/disable cancel button based on remarks length (minimum 6 characters)
$('#op_bal_cancel_remark').on('keyup', function () {
    if (this.value.trim().length > 6) {
        $('#op_bal_cancel_confirm').prop('disabled', false);
    } else {
        $('#op_bal_cancel_confirm').prop('disabled', true);
    }
});

// Cancel op balance record via AJAX with remarks
$('#op_bal_cancel_confirm').on('click', function () {
    var cancelBtn = $(this);
    cancelBtn.prop('disabled', true);
    my_Date = new Date();
    $.ajax({
        type: 'POST',
        url: base_url + "index.php/admin_ret_purchase/smith_cmpy_op_bal/delete/" + $('#id_op_bal_cancel').val() + "?nocache=" + my_Date.getUTCSeconds(),
        dataType: 'json',
        data: { 'cancel_remark': $('#op_bal_cancel_remark').val() },
        success: function (data) {
            $('#confirm-opbal-cancel').modal('hide');
            if (data.status) {
                $.toaster({ priority: 'success', title: 'Success!', message: '</br>' + data.message });
                get_smith_cmpy_op_bal_details();
            } else {
                $.toaster({ priority: 'danger', title: 'Error!', message: '</br>' + data.message });
            }
        },
        error: function () {
            $('#confirm-opbal-cancel').modal('hide');
            $.toaster({ priority: 'danger', title: 'Error!', message: 'Failed to cancel record.' });
        }
    });
});



