/*Non Tag Receipt*/

(function () {

    const MODULE_SCOPE = '#creditDebitModule';

    const fieldConfig = {
        '#trans_amount': { label: 'Amount', enabled: true },
        '#trans_weight': { label: 'Weight', enabled: true }
    };

    $(MODULE_SCOPE).on('input', Object.keys(fieldConfig).join(','), function () {

        const $field = $(this);
        const config = fieldConfig['#' + $field.attr('id')];

        if (!config || !config.enabled) return;

        const value = $field.val().trim();
        const numericValue = parseFloat(value);

        if (value === '') return;

        if (!isNaN(numericValue) && numericValue < 0) {

            $field.val('');

            $.toaster({
                priority: 'danger',
                title: 'Warning!',
                message: `</br>${config.label} cannot be negative.`
            });
        }
    });

})();




$('#save_credit_entry').on('click', function () {

    var karigar_bills_val = $("#select_karigar_bills").val();
    var has_po = (karigar_bills_val != null && karigar_bills_val != '');

    if (($('#trans_amount').val() == '' || $('#trans_amount').val() == 0) && ($('#trans_weight').val() == '' || $('#trans_weight').val() == 0)) {

        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Please Enther the " + ($("#transaction_in").val() == 1) ? "Amount" : "Weight" });

    }

    else if (has_po && $('#trans_amount').val() > Math.abs(parseFloat(karigar_bills_val.split("[~s~]")[0])) && parseFloat($('#trans_amount').val())>0) {

        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Payment amount Pending Limit Exceeded." });

    }

    else if (has_po && $('#trans_weight').val() > Math.abs(parseFloat(karigar_bills_val.split("[~s~]")[0])) && parseFloat($('#trans_weight').val())>0) {

         $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Payment weight Pending Limit Exceeded." });

    }

    else if ($('#select_karigar').val() == '' || $('#select_karigar').val() == null) {

        $.toaster({ priority: 'danger', title: 'Warning!', message: '' + "</br>Please Select the Karigar." });

    } else {

        my_Date = new Date();

        if ($('#crdrid').val() == "") {

            var url = base_url + "index.php/admin_ret_purchase/credit_debit_entry/save?nocache=" + my_Date.getUTCSeconds() + '' + my_Date.getUTCMinutes() + '' + my_Date.getUTCHours();

        }

        else {

            var url = base_url + "index.php/admin_ret_purchase/credit_debit_entry/update?nocache=" + my_Date.getUTCSeconds() + '' + my_Date.getUTCMinutes() + '' + my_Date.getUTCHours();

        }

        $('#save_credit_entry').prop('disabled', true);

        var selectedValue = $('input[name="credit[accountto]"]:checked').val();

        var po_id_val = has_po ? karigar_bills_val.split("[~s~]")[1] : '';
        var ratecut_val = has_po ? karigar_bills_val.split("[~s~]")[2] : '';

        $.ajax({

            url: url,

            type: 'POST',

            data: {
                'karigar': $('#select_karigar').val(), 'accountto': selectedValue, 'crdrid': $('#crdrid').val(), 'po_id': po_id_val, 'ratecut': ratecut_val,

                'transamount': $('#trans_amount').val(), 'transweight': $('#trans_weight').val(), 'transactionin': $('#transaction_in').val(), 'naration': $('#naration').val(), 'transtype': $('#transtype').val(), 'wtranstype': $('#wtranstype').val(), 'id_cr_dr_ledger': $('#id_cr_dr_ledger').val()
            },

            dataType: 'json',

            success: function (data) {

                if (data.status == true) {

                    $.toaster({ priority: 'success', title: 'Success!', message: '' + "</br> Credit Entry Saved SuccessFully..." });

                    window.location.href = base_url + 'index.php/admin_ret_purchase/credit_debit_entry/list';

                    $("div.overlay").css("display", "none");

                }

                else {

                    $.toaster({ priority: 'warning', title: 'Success!', message: '' + "</br> Unable to Credit Entry" });

                    window.location.reload();

                    $("div.overlay").css("display", "none");

                }

            },

            error: function (error) {

                $("div.overlay").css("display", "none");

            }

        });

    }

});



