document.addEventListener('DOMContentLoaded', function () {
    var toggleElements = document.querySelectorAll('.toggle-transaction');

    toggleElements.forEach(function (toggle) {
        toggle.addEventListener('change', function () {
            var transactionInput = document.getElementById('transaction_in');
            var weight_row = document.getElementById('weight_row');
            var amount_row = document.getElementById('amount_row');
            var trans_in = document.getElementById('transaction-in');
            var ledger_row = document.getElementById('ledger_row_wrapper');
            var isSmith = $('input[name="credit[accountto]"]:checked').val() == "2";
            if (this.checked) {
                transactionInput.value = '1';
                weight_row.style.display = 'none';
                amount_row.style.display = 'block';
                if(ledger_row) ledger_row.style.display = 'block';
                trans_in.innerHTML = "Amount";
                // Don't override Smith selection when toggling to Amount
                if (!isSmith) $("#accountto1").click();
            } else {
                // If Smith is selected, prevent switching to Weight
                if (isSmith) {
                    this.checked = true;
                    return;
                }
                transactionInput.value = '0';
                weight_row.style.display = 'block';
                amount_row.style.display = 'none';
                if(ledger_row) ledger_row.style.display = 'none';
                $("#id_cr_dr_ledger").val('').trigger('change');
                trans_in.innerHTML = "Weight";
                $("#accountto3").click();
            }
        });
    });
});

