function get_all_payment_pending_po_bills(balance) {

    // CPO-08: Bill Type = ADVANCE (4) pays against a purchase commitment, not
    // invoices, so there is no pending-bill list to fetch. Skipping the call also
    // avoids firing it before a supplier is chosen, which used to 500.
    if ($('#bill_type_common_po').length && $('#bill_type_common_po').is(':checked')) {
        $('#pending_bills_container').html('');
        return;
    }

    $("div.overlay").css("display", "block");
    $('.balance_amount').val(0);
    $('.receive_amount').val(0);
    var bill_type = $("input[name='billing[bill_type]']:checked").val(); //1-Bill , 2-Receipt
    if (ctrl_page[1] == 'karigarmetalissue') {
        bill_type = 2;
    }
    else if (ctrl_page[1] == 'supplier_rate_cut') {
        bill_type = 3;
    }
    if (parseFloat(balance.balance_amount) == 0) {
        // The overlay is switched on a few lines above; every other exit from this
        // function turns it off in the AJAX callbacks, but this early return did not —
        // so a supplier with a zero balance left the spinner running forever.
        $("div.overlay").css("display", "none");
        $('#pending_bills_container').html("");
        return;
    }
    var grn_type_val = (bill_type == '2') ? '4' : '1';
    $.ajax({
        type: 'POST',
        url: base_url + 'index.php/admin_ret_purchase/getPending_payment_po_bills_for_payment',
        // dataType: 'json',
        data: { 'id_karigar': $('#select_karigar').val(), 'bill_type': bill_type, 'id_metal': isNaN($('#select_metal').val()) ? 0 : $('#select_metal').val(), "opening_checked": $('#opening_checked').val(), 'grn_type': grn_type_val },
        success: function (datas) {

            // SPS-11: the grid carries a per-row "Pay Now" box so a bill can be
            // part-settled. The Outstanding column is the balance the server re-derives
            // and validates against on save, so the two can never disagree.

            var tableHtml = '<table class="table table-bordered table-striped" id="pending_payment_table">' +
                '<thead>' +
                '<tr>' +
                '<th width="100px">' +
                '<div class="checkbox-wrapper-32"><input type="checkbox" id="selectAll" class="select-all-checkbox" checked><svg viewBox="0 0 35.6 35.6">' +
                '<circle class="background" cx="17.8" cy="17.8" r="17.8"></circle>' +
                '<circle class="stroke" cx="17.8" cy="17.8" r="14.37"></circle>' +
                '<polyline class="check" points="11.78 18.12 15.55 22.23 25.17 12.87"></polyline></svg></div> Select All' +
                '</th>' +
                '<th>Reference No</th>' +
                '<th class="text-right">Outstanding</th>' +
                '<th class="text-right" style="width:130px;">Pay Now</th>' +
                '</tr>' +
                '</thead>' +
                '<tbody>';

            var hasData = false;
            var total_recs = 0;
            var dataHTML = "";
            var total_amount = 0;
            var parts = datas.split("[~s~]");
            var data = JSON.parse(parts[0]);
            var karigar_det = JSON.parse(parts[1]);
            $("#payee_name").val(karigar_det.acc_holder_name);
            $.each(data, function (key, value) {
                if (value.category != 'PAYMENT' && parseFloat(value.trans_amount) > 0) {
                    hasData = true;
                    // Using loop index (key) as unique identifier suffix to avoid issues with special chars in referenceno if any
                    var rowId = key;
                    var outstanding = parseFloat(value.trans_amount) || 0;

                    // Defaults to the full outstanding balance; the operator overtypes it
                    // to part-settle. The max attribute is a convenience only - the real
                    // ceiling is enforced in sps_sync_row() and again on the server.
                    var payBox = '<input type="number" step="0.01" min="0" max="' + outstanding.toFixed(2) + '" ' +
                        'class="form-control text-right pay_amt_input" ' +
                        'id="amount_paid_' + rowId + '" data-row="' + rowId + '" ' +
                        'value="' + outstanding.toFixed(2) + '">';

                    dataHTML += '<tr class="pending_payment_rows" id="row_' + rowId + '">' +
                        '<td><div class="checkbox-wrapper-32"><input type="checkbox" class="bill-checkbox" id="cb_' + rowId + '" name="billing[' + key + '][bill_ids][]" data-row="' + rowId + '" checked><svg viewBox="0 0 35.6 35.6">' +
                        '<circle class="background" cx="17.8" cy="17.8" r="17.8"></circle>' +
                        '<circle class="stroke" cx="17.8" cy="17.8" r="14.37"></circle>' +
                        '<polyline class="check" points="11.78 18.12 15.55 22.23 25.17 12.87"></polyline></svg> </div>' + parseInt(rowId + 1) + '. </td>' +
                        '<td>' + value.referenceno +
                        '<input type="hidden" id="billing[bill_ref_no_' + rowId + ']" name="billing[bill_ref_no_' + rowId + ']" value="' + value.po_id + '">' +
                        '<input type="hidden" id="billing[bill_rate_no_' + rowId + ']" name="billing[bill_rate_no_' + rowId + ']" value="' + value.ratecut + '">' +
                        '<input type="hidden" id="billing[bill_checked_' + rowId + ']" name="billing[bill_checked_' + rowId + ']" class="all_select" value="1">' +
                        '<input type="hidden" id="billing[type_' + rowId + ']" name="billing[type_' + rowId + ']" value="' + value.type + '">' +
                        '</td>' +
                        '<td style="text-align: right;" class="sps-outstanding">' + money_format_india(value.trans_amount) +
                        '<input type="hidden" id="billing[bill_amount_' + rowId + ']" name="billing[bill_amount_' + rowId + ']" value="' + value.trans_amount + '">' +
                        '</td>' +
                        '<td>' + payBox +
                        '<input type="hidden" id="billing[amount_paid_' + rowId + ']" name="billing[amount_paid_' + rowId + ']" value="' + outstanding.toFixed(2) + '">' +
                        '</td>' +
                        '</tr>';
                    total_recs = rowId;
                    total_amount += outstanding;
                }
            });

            tableHtml += dataHTML + '</tbody><tfoot><td colspan="2">Total</td>' +
                '<td style="text-align: right;">' + money_format_india(total_amount.toFixed(2)) + '</td>' +
                '<td style="text-align: right;"><span class="selected-total"></span></td></tfoot></table>';

            // Add select all/clear all buttons
            if (hasData) {
                tableHtml += '<div class="checkbox-controls" style="margin-top: 10px;">' +
                    '<button type="button" class="btn btn-sm btn-primary select-all-btn">Select All</button> ' +
                    '<button type="button" class="btn btn-sm btn-secondary clear-all-btn">Clear All</button>' +
                    '</div>';
            }
            if (parseInt(balance.balance_amount) != 0)
                $("#payment_method").css('display', "flex");
            else
                $("#payment_method").css('display', "none");
            tableHtml += '<input type="hidden" id="billing[total_entries]" name="billing[total_entries]" value="' + total_recs + '">';
            $('#pending_bills_container').html(tableHtml);

            // Initialize calculations
            calculateSelectedTotal();

            if (!hasData) {
                if (!$("#opening_checkbox").prop("checked"))
                    $("#opening_checkbox").click();
                else
                    $('#pending_bills_container').html('<p>No pending bills found.</p>');
            }
            
            calculatePaymentCost();
            // The overlay is switched on before the request but was never switched
            // off on either callback, so the spinner stayed up after every fetch.
            $("div.overlay").css("display", "none");
        },
        error: function (error) {
            $("div.overlay").css("display", "none");
            $.toaster({ priority: 'danger', title: 'Warning!', message: '</br>Unable to load pending bills' });
        }
    });
    // PUR-CLT03: Removed synchronous balance_amount set here.
    // calculateSelectedTotal() inside the AJAX success callback is now
    // the sole authority for setting #balance_amount based on checked bills.
}

/* SPS: rounding allowance, in rupees, when comparing a typed settlement amount against
   the outstanding balance. Mirrors Ret_purchase_order_model::SETTLEMENT_TOLERANCE - the
   server re-validates every allocation independently, so if the two ever disagree the
   server wins and the save is refused. Keep them in step. */
var SPS_TOLERANCE = 0.05;

/* Outstanding balance of one grid row. */
function sps_row_outstanding(rowId) {
    return parseFloat($('#billing\\[bill_amount_' + rowId + '\\]').val()) || 0;
}

/* Amount being settled against one grid row: what the operator typed, clamped to the
   outstanding balance, and 0 when the row is not ticked. The hidden amount_paid_N field
   is the value that actually posts, so it is rewritten here rather than being left at
   whatever the row was rendered with. */
function sps_sync_row(rowId) {
    var checked = $('#cb_' + rowId).is(':checked');
    var outstanding = sps_row_outstanding(rowId);
    var box = $('#amount_paid_' + rowId);

    var raw = box.length ? (parseFloat(box.val()) || 0) : outstanding;
    var amount = raw;

    if (amount > outstanding) {
        amount = outstanding;
    }
    if (amount < 0) {
        amount = 0;
    }

    /* Write back ONLY when the value was genuinely clamped - never merely to reformat.
       Comparing box.val() against amount.toFixed(2) as STRINGS meant that typing "1"
       rewrote the box to "1.00" on the very next keystroke, so a figure longer than one
       digit could not be entered at all. The comparison is numeric, with an epsilon well
       below one paise, so a half-typed "15" is left alone while a real clamp still
       corrects the box. */
    if (box.length && Math.abs(amount - raw) > 0.0001) {
        box.val(amount.toFixed(2));
    }

    $('#billing\\[amount_paid_' + rowId + '\\]').val(checked ? amount.toFixed(2) : '0');

    return checked ? amount : 0;
}

// Calculate total of selected checkboxes
function calculateSelectedTotal() {
    var total = 0;

    /* SPS-11: sums what is actually being PAID on each ticked row, not the row's full
       bill value. Previously this summed bill_amount_N, so the Net Amount box always
       showed the full value of every ticked bill and a part-payment could not be
       expressed at all. */
    $('.bill-checkbox').each(function () {
        var rowId = $(this).data('row');
        total += sps_sync_row(rowId);
    });

    total = Math.round(total * 100) / 100;

    $('.selected-total').text(total.toFixed(2));

    // Update balance amount with selected total
    $('#balance_amount').val(total.toFixed(2));
    if ($('#opening_checked').val() == "0") {
        $("#receive_amount_net_amount").val(total.toFixed(2));
    }

    /* Do not steal focus while the operator is typing an allocation.

       This focus() predates SPS and was harmless when calculateSelectedTotal() only ran
       on a checkbox click. It now also runs on every keystroke in a Pay Now box, so it
       moved the cursor to Net Amount after the FIRST character and the amount could not
       be typed. The guard is narrow on purpose: focus still jumps to Net Amount when the
       total changes through a checkbox, Select All or Clear All, exactly as before. */
    if (!$(document.activeElement).hasClass('pay_amt_input')) {
        $("#balance_amount").focus();
    }
    return total;
}

// Select All functionality
$(document).on('click', '#selectAll', function () {
    var isChecked = $(this).is(':checked');
    $('.all_select').val(isChecked ? 1 : 0);
    $('.bill-checkbox').prop('checked', isChecked);
    calculateSelectedTotal();
});

