$(document).on('click', '#pending_payment_table tr', function (e) {

    // ðŸš« prevent double toggle if checkbox itself clicked
    if ($(e.target).is('input[type="checkbox"]')) {
        return;
    }

    /* SPS-11: the row now contains a Pay Now box. Without this guard, clicking into it
       to type an amount would toggle the whole row off underneath the cursor. */
    if ($(e.target).is('input, select, textarea, label')) {
        return;
    }

    var checkbox = $(this).find('input[type="checkbox"]').first();
    var isChecked = !checkbox.prop('checked');
    checkbox.prop('checked', isChecked);

    // Update hidden field
    var rowId = checkbox.data('row');
    $('#billing\\[bill_checked_' + rowId + '\\]').val(isChecked ? 1 : 0);

    calculateSelectedTotal();
    calculatePaymentCost();
});


/* SPS-11: per-row Pay Now box.
   The previous version of this handler was dead code - no element ever carried the
   .pay_amt_input class - and it read '#biling[bill_amount_N]', a typo for 'billing',
   so its ceiling check compared against 0 regardless. The box now exists, and the
   ceiling is enforced in sps_sync_row() against the row's outstanding balance.
   Typing an amount ticks the row on, saving the operator a second click. */
$(document).on('keyup change', '.pay_amt_input', function () {
    var rowId = $(this).data('row');
    var outstanding = sps_row_outstanding(rowId);
    var payAmount = parseFloat($(this).val()) || 0;

    // SPS_TOLERANCE mirrors Ret_purchase_order_model::SETTLEMENT_TOLERANCE - a rounding
    // allowance so a figure typed to the paise is not rejected by float drift.
    if (payAmount > outstanding + SPS_TOLERANCE) {
        $(this).val(outstanding.toFixed(2));
        $.toaster({
            priority: 'warning', title: 'Capped',
            message: '</br>Cannot pay more than the outstanding balance of ' + outstanding.toFixed(2)
        });
    }

    if (payAmount > 0 && !$('#cb_' + rowId).is(':checked')) {
        $('#cb_' + rowId).prop('checked', true);
        $('#billing\\[bill_checked_' + rowId + '\\]').val(1);
    }

    calculateSelectedTotal();
    calculatePaymentCost();
});

/* SPS-11: typing a lump sum into Net Amount spreads it over the pending bills, first
   row first - the same order the server uses to allocate in Cumulative mode.

   The previous version refused to part-pay ("Do not allow partial payment"): it ticked
   only bills whose FULL value fitted inside the remaining balance and stopped at the
   first one that did not, so 400000 against a 1000000 bill selected nothing at all.
   The remainder now part-pays the next bill, which is acceptance criteria #1 and #3. */
$(document).on('keyup', '.balance_amount', function () {
    var balance = parseFloat($(this).val()) || 0;

    $('.bill-checkbox').prop('checked', false);
    $('.all_select').val(0);

    $('.bill-checkbox').each(function () {

        var row_id = $(this).data('row');
        var bill_amount = sps_row_outstanding(row_id);

        if (bill_amount <= 0) {
            return true; // nothing left on this row, try the next
        }

        if (balance >= bill_amount) {
            // Settle this bill in full and carry the rest forward.
            $(this).prop('checked', true);
            $('#billing\\[bill_checked_' + row_id + '\\]').val(1);
            $('#amount_paid_' + row_id).val(bill_amount.toFixed(2));
            balance = Math.round((balance - bill_amount) * 100) / 100;

        } else if (balance > 0) {
            // Part-settle this bill with what is left, then stop.
            $(this).prop('checked', true);
            $('#billing\\[bill_checked_' + row_id + '\\]').val(1);
            $('#amount_paid_' + row_id).val(balance.toFixed(2));
            balance = 0;
            return false;

        } else {
            return false;
        }
    });

    /* Push the per-row figures into the hidden fields that actually post. Deliberately
       NOT calculateSelectedTotal() - that writes back into #balance_amount, which is the
       box the operator is still typing in. */
    $('.bill-checkbox').each(function () {
        sps_sync_row($(this).data('row'));
    });
    calculatePaymentCost();
});



