// Open debit note modal and load debit entries
$(document).on('click', '#debit_note_modal_btn', function () {
    var karigar_id = $('#select_karigar').val();
    if (!karigar_id || karigar_id == '') {
        $.toaster({ priority: 'danger', title: 'Warning!', message: 'Please select a Karigar first.' });
        return;
    }
    
    var bill_type = $("input[name='billing[bill_type]']:checked").val(); // 1=Bill(Supplier), 2=Receipt(Smith)
    $.ajax({
        type: 'POST',
        url: base_url + 'index.php/admin_ret_purchase/get_crdr_debit_entries_for_payment',
        dataType: 'json',
        data: { 'id_karigar': karigar_id, 'bill_type': bill_type },
        success: function (data) {
            render_debit_modal(data);
            $('#debit_note_modal').modal('show');
        },
        error: function () {
            $.toaster({ priority: 'danger', title: 'Error!', message: 'Failed to load debit entries.' });
        }
    });
});

// Render debit entries in modal (unified: CR/DR + Purchase Returns) — No PO assignment
function render_debit_modal(data) {
    var tbody = $('#debit_entries_table tbody');
    tbody.empty();
    
    if (!data || data.length == 0) {
        tbody.append('<tr><td colspan="9" class="text-center">No entries found.</td></tr>');
        return;
    }
    
    // Load previously saved adjustments (both types)
    var saved_debit_adj = [];
    var saved_return_adj = [];
    var saved_debit_json = $('#debit_adjustments_data').val();
    var saved_return_json = $('#purchase_return_adjustments_data').val();
    if (saved_debit_json != '') {
        try { saved_debit_adj = JSON.parse(saved_debit_json); } catch(e) {}
    }
    if (saved_return_json != '') {
        try { saved_return_adj = JSON.parse(saved_return_json); } catch(e) {}
    }
    
    $.each(data, function (key, item) {
        var is_checked = '';
        var saved_amount = '';
        
        // Check if this entry was previously saved
        if (item.entry_type == 'crdr') {
            var prev = saved_debit_adj.find(function(a) { return a.crdrid == item.entry_id; });
            if (prev) { is_checked = 'checked'; saved_amount = prev.amount; }
        } else if (item.entry_type == 'purchase_return') {
            var prev = saved_return_adj.find(function(a) { return a.pur_return_id == item.entry_id; });
            if (prev) { is_checked = 'checked'; saved_amount = prev.amount; }
        }
        
        var balance = parseFloat(item.balance_amount);
        var adjust_val = saved_amount !== '' ? parseFloat(saved_amount).toFixed(2) : balance.toFixed(2);
        
        // Source label with color coding
        var source_label = item.source == 'Purchase Return' 
            ? '<span class="label label-warning">' + item.source + '</span>' 
            : '<span class="label label-info">' + item.source + '</span>';
        
        var row = '<tr>' +
            '<td><input type="checkbox" class="debit-entry-checkbox" data-entry-id="' + item.entry_id + '" data-entry-type="' + item.entry_type + '" data-balance="' + balance.toFixed(2) + '" data-refno="' + item.referenceno + '" ' + is_checked + '></td>' +
            '<td>' + source_label + '</td>' +
            '<td>' + item.referenceno + '</td>' +
            '<td>' + item.entry_date + '</td>' +
            '<td style="text-align:right;">' + parseFloat(item.total_amount).toFixed(2) + '</td>' +
            '<td style="text-align:right;">' + parseFloat(item.spent_amount).toFixed(2) + '</td>' +
            '<td style="text-align:right;">' + balance.toFixed(2) + '</td>' +
            '<td><input type="number" class="form-control debit-adjust-amount" data-entry-id="' + item.entry_id + '" data-entry-type="' + item.entry_type + '" value="' + adjust_val + '" max="' + balance.toFixed(2) + '" min="0" step="0.01" style="width:100px; text-align:right;"></td>' +
            '<td>' + (item.naration || '') + '</td>' +
            '</tr>';
        tbody.append(row);
    });
    
    calculate_debit_total();
}

// Calculate debit total from Adjust Amount inputs (only checked rows)
function calculate_debit_total() {
    var total = 0;
    $('.debit-entry-checkbox:checked').each(function () {
        var adj_amount = parseFloat($(this).closest('tr').find('.debit-adjust-amount').val()) || 0;
        total += adj_amount;
    });
    $('.debit_total_amount').text(total.toFixed(2));
}

// On debit checkbox change
$(document).on('change', '.debit-entry-checkbox', function () {
    calculate_debit_total();
});

// On adjust amount change — validate and recalculate
$(document).on('keyup change', '.debit-adjust-amount', function () {
    var max = parseFloat($(this).attr('max')) || 0;
    var val = parseFloat($(this).val());
    
    // Validation: must be a number
    if (isNaN(val)) {
        $(this).val(max.toFixed(2));
        $.toaster({ priority: 'danger', title: 'Warning!', message: 'Please enter a valid number.' });
        calculate_debit_total();
        return;
    }
    // Validation: no negative
    if (val < 0) {
        $(this).val('0.00');
        $.toaster({ priority: 'danger', title: 'Warning!', message: 'Amount cannot be negative.' });
        calculate_debit_total();
        return;
    }
    // Validation: cannot exceed balance
    if (val > max) {
        $(this).val(max.toFixed(2));
        $.toaster({ priority: 'danger', title: 'Warning!', message: 'Amount cannot exceed balance (' + max.toFixed(2) + ').' });
    }
    calculate_debit_total();
});

// Save debit adjustments (unified: CR/DR + Purchase Returns) — No PO assignment
$(document).on('click', '#save_debit_adjustments', function () {
    var crdr_adjustments = [];
    var return_adjustments = [];
    var valid = true;
    
    $('.debit-entry-checkbox:checked').each(function () {
        var entry_id = $(this).data('entry-id');
        var entry_type = $(this).data('entry-type');
        var balance = parseFloat($(this).data('balance')) || 0;
        var refno = $(this).data('refno');
        var amount = parseFloat($(this).closest('tr').find('.debit-adjust-amount').val());
        
        // Validation: valid number
        if (isNaN(amount)) {
            valid = false;
            $.toaster({ priority: 'danger', title: 'Warning!', message: 'Please enter a valid adjust amount for "' + refno + '".' });
            return false;
        }
        
        // Validation: positive amount
        if (amount <= 0) {
            valid = false;
            $.toaster({ priority: 'danger', title: 'Warning!', message: 'Adjust amount must be greater than zero for "' + refno + '".' });
            return false;
        }
        
        // Validation: cannot exceed balance
        if (amount > balance) {
            valid = false;
            $.toaster({ priority: 'danger', title: 'Warning!', message: 'Adjust amount cannot exceed balance (' + balance.toFixed(2) + ') for "' + refno + '".' });
            return false;
        }
        
        if (entry_type == 'crdr') {
            crdr_adjustments.push({
                'crdrid': entry_id,
                'amount': amount,
                'refno': refno
            });
        } else if (entry_type == 'purchase_return') {
            return_adjustments.push({
                'pur_return_id': entry_id,
                'amount': amount,
                'refno': refno
            });
        }
    });
    
    if (!valid) return;
    
    // Store adjustments as separate JSON fields
    $('#debit_adjustments_data').val(JSON.stringify(crdr_adjustments));
    $('#purchase_return_adjustments_data').val(JSON.stringify(return_adjustments));
    
    // Calculate total adjustment amount (both types combined)
    var total_debit = 0;
    crdr_adjustments.forEach(function(adj) { total_debit += adj.amount; });
    return_adjustments.forEach(function(adj) { total_debit += adj.amount; });
    
    // Update right-side display
    $('#tot_debit_adj_amt').text(total_debit > 0 ? total_debit.toFixed(2) : '');
    
    // Recalculate totals
    calculateSelectedTotal();
    calculatePaymentCost();
    
    $('#debit_note_modal').modal('hide');
    $.toaster({ priority: 'success', title: 'Success!', message: 'Adjustments saved.' });
});
